export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, tt = u / g;
  const t = sdk.clamp(time, 0, T);
  const h = Math.max(0, u * t - g * t * t / 2);
  let v = u - g * t;
  const atTop = Math.abs(t - tt) < 1e-6;
  if (atTop) v = 0;
  const F = m * g;
  let st;
  if (t <= 0) st = 'Ready to toss';
  else if (t >= T - 1e-9) st = 'Back at launch height';
  else if (atTop) st = 'At the top';
  else if (v > 0) st = 'Rising';
  else st = 'Falling';
  const by = 370 - h * (300 / 2.2);
  const bx = 165;
  const f = (x) => u - g * x;
  const pt = (x) => ({ x: x, y: f(x) });
  const te = Math.max(t, 0.001);
  const trace = [];
  for (let i = 0; i <= 11; i++) trace.push(pt(te * i / 11));
  const cont = [];
  const tc = Math.min(T, Math.max(te + 0.001, te));
  const t2 = Math.max(T, te + 0.002);
  for (let i = 0; i <= 11; i++) cont.push(pt(tc + (t2 - tc) * i / 11));
  const a0 = Math.max(0, t - 0.2), a1 = Math.min(T, t + 0.2);
  const seg = [pt(a0), pt(a1 > a0 ? a1 : a0 + 0.01)];
  const objs = [];
  objs.push(...sdk.panel({ id: 'lane.motion', x: 10, y: 34, w: 300, h: 370, title: 'The motion', state: st }));
  objs.push(...sdk.panel({ id: 'lane.graph', x: 320, y: 34, w: 310, h: 370, title: 'Velocity over time', state: 'v = u - g t' }));
  objs.push(sdk.axis('axis.height', { x: 70, y: 370, length: 300, orientation: 'y', min: 0, max: 2.2, ticks: [0, 0.5, 1, 1.5, 2], label: 'Height', unit: 'm' }));
  objs.push(sdk.circle('ball.toss', bx, by, 26));
  objs.push(...sdk.vector('vec.v', { x: 195, y: by }, { value: v, direction: 'up' }, { scale: 14, label: 'v', role: 'observed' }));
  objs.push(...sdk.vector('vec.a', { x: 125, y: by }, { value: -g, direction: 'up' }, { scale: 4, label: 'a', role: 'warning' }));
  objs.push(...sdk.callout(228, sdk.clamp(by, 80, 340), ['v ' + sdk.format(v, 2) + ' m/s', 'a ' + sdk.format(-g, 1) + ' m/s²', 'F ' + sdk.format(F, 1) + ' N'], { id: 'callout.toss' }));
  objs.push(sdk.plot('plot.vt', { x: 335, y: 60, w: 290, h: 280, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' } }, series: [
    { label: 'v up to now', kind: 'line', points: trace },
    { label: 'continuation', kind: 'line', points: cont },
    { label: 'slope a = -g', kind: 'line', points: seg }
  ] }));
  objs.push(sdk.text('plot.vt.note', 480, 392, 'slope a = -g = ' + sdk.format(-g, 1) + ' m/s²', { align: 'middle' }));
  return {
    frame: { width: 640, height: 420, objects: objs, readouts: [
      { id: 'velocity', value: v }, { id: 'acceleration', value: -g }, { id: 'force', value: F }, { id: 'motionState', value: st }
    ] },
    quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: tt, apexHeight: u * u / (2 * g), height: h, velocity: v, acceleration: -g, force: F }
  };
}
